package net.civeira.phylax.features.access.userprofile.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class GenderVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property gender of user profile ")
  void test_gender_v_o_builder() {
    Assertions.assertFalse(GenderVO.nullValue().getGender().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(GenderVO.tryFrom(null).getGender().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one", GenderVO.from("one").getGender().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> GenderVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", GenderVO.from("one").toString());
  }
}
